#!/usr/bin/env python3
"""Reconstruct the exact evaluated v311. No solver runs or eval registration.
Only line edits are encoded; the existing v105 weights are not duplicated.
"""
from pathlib import Path
import base64,difflib,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
PARENT="1f55b1534b9e912a2cc8db3386cd6c1fe9515e417d0462a9300562b75a51ae58"
EXPECTED="c3f819c2715f397bee0ca95bca12be3196c6f5531dbfeb19358d0afd5f6868ea"
PAYLOAD=""
source=ROOT/"src/bin/v105_nn_lns.cpp"
raw=source.read_bytes()
assert hashlib.sha256(raw).hexdigest()==PARENT,"v105 parent changed"
lines=raw.decode().splitlines(True)
for first,last,replacement in reversed(json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))):
    lines[first:last]=replacement
result="".join(lines)
assert hashlib.sha256(result.encode()).hexdigest()==EXPECTED,"reconstruction hash mismatch"
output=ROOT/"src/bin/v311_neural_multistart.cpp"
if output.exists():
    assert output.read_bytes()==result.encode(),"refusing to overwrite different v311"
else:
    output.write_text(result)
patch=ROOT/"adhoc/v311/v311_vs_v105.patch"
patch.parent.mkdir(parents=True,exist_ok=True)
patch.write_text("".join(difflib.unified_diff(raw.decode().splitlines(True),lines,fromfile="a/src/bin/v105_nn_lns.cpp",tofile="b/src/bin/v311_neural_multistart.cpp")))
print(EXPECTED,output)
